import base64,hashlib,json,os,subprocess
from pathlib import Path
r=Path('/dataset/shaoshitong/search-r1-rl/bapo-e1-instruct300-ray-titlefix-20261006')
files={'cpu-tests.py': '', 'capture-runtime-executable.py': ''}
for name,encoded in files.items():
 raw=base64.b64decode(encoded)
 with (r/'tools'/name).open('xb') as f:f.write(raw)
 print('CPU_ONLY_TOOL_INSTALLED',name,hashlib.sha256(raw).hexdigest(),flush=True)
env=dict(os.environ,PYTHONPATH=str(r/'repo'),PYTHONDONTWRITEBYTECODE='1',CUDA_VISIBLE_DEVICES='',HF_HUB_OFFLINE='1',HF_DATASETS_OFFLINE='1')
with (r/'logs/runtime-capture.log').open('x') as log:
 subprocess.run([str(r/'env/bin/python'),'-B',str(r/'tools/capture-runtime-executable.py'),'484c0b30fa73fa5354bdb3452f007134ec5db13f'],cwd=r/'repo',env=env,stdout=log,stderr=subprocess.STDOUT,check=True)
with (r/'logs/cpu-gate.log').open('x') as log:
 result=subprocess.run([str(r/'env/bin/python'),'-B',str(r/'tools/cpu-tests.py')],cwd=r/'repo',env=env,stdout=log,stderr=subprocess.STDOUT)
print(json.dumps({'cpu_exit':result.returncode,'root':str(r),'training_submitted':False}),flush=True)
raise SystemExit(result.returncode)
